insert into public.questions (id, subject_id, topic_id, exam_id, question, option_a, option_b, option_c, option_d, correct_option, explanation, tags, source, difficulty, status, created_at) values
  ('b28c499c-7cb4-52dd-a471-6f872c67eb3d', '9fe02e81-117a-5b9f-a89f-6c4b34a7453c', '9d396a89-bf98-504e-a9a9-4fb1e2edb893', 'b95444e3-f3f0-565d-aa0e-2c621416d98d', 'The price of a book rises from ₹200 to ₹250. What is the percentage increase?', '20%', '25%', '30%', '50%', 'B', 'Increase = 250 − 200 = ₹50. Percentage increase = 50 ÷ 200 × 100 = 25%.', array['aptitude','percentage']::text[], 'StudyVeda original', 'easy', 'published', '2026-10-26T00:00:00.000Z'),
  ('2ced367b-3896-5eb5-ae8b-32c274547299', '9fe02e81-117a-5b9f-a89f-6c4b34a7453c', '9d396a89-bf98-504e-a9a9-4fb1e2edb893', 'b95444e3-f3f0-565d-aa0e-2c621416d98d', 'A number is first increased by 10% and then decreased by 10%. What is the net change?', 'No change', '1% increase', '1% decrease', '2% decrease', 'C', 'Take 100. After +10% it is 110; after −10% it is 99. Net change = −1, i.e. a 1% decrease.', array['aptitude','percentage']::text[], 'StudyVeda original', 'medium', 'published', '2026-10-26T00:01:00.000Z'),
  ('b60da1c6-f736-5f9c-ad52-57e55d6058eb', '9fe02e81-117a-5b9f-a89f-6c4b34a7453c', '9d396a89-bf98-504e-a9a9-4fb1e2edb893', '17c77b05-515c-5f69-acb3-22f15e6a4993', 'What is 15% of 480?', '62', '72', '82', '68', 'B', '15% of 480 = 0.15 × 480 = 72.', array['aptitude','percentage']::text[], 'StudyVeda original', 'easy', 'published', '2026-10-26T00:02:00.000Z'),
  ('9edaab8b-d00b-571e-a054-685564f2141b', '9fe02e81-117a-5b9f-a89f-6c4b34a7453c', '044995bd-7914-5738-aeff-f655a0fc4b00', '17c77b05-515c-5f69-acb3-22f15e6a4993', 'An article bought for ₹800 is sold for ₹920. What is the profit percentage?', '12%', '15%', '18%', '20%', 'B', 'Profit = ₹120. Profit % = 120 ÷ 800 × 100 = 15%.', array['aptitude','profit-and-loss']::text[], 'StudyVeda original', 'easy', 'published', '2026-10-26T00:03:00.000Z'),
  ('fa079b77-dc83-54d8-ac5b-327d7bbd6247', '9fe02e81-117a-5b9f-a89f-6c4b34a7453c', '044995bd-7914-5738-aeff-f655a0fc4b00', 'b95444e3-f3f0-565d-aa0e-2c621416d98d', 'A shopkeeper sells an item for ₹540 at a loss of 10%. What was the cost price?', '₹594', '₹600', '₹580', '₹610', 'B', 'Selling price = 90% of cost price, so cost price = 540 ÷ 0.9 = ₹600.', array['aptitude','profit-and-loss']::text[], 'StudyVeda original', 'medium', 'published', '2026-10-26T00:04:00.000Z'),
  ('a2becd51-5ccc-5b88-ad94-f5ca0a3584de', '9fe02e81-117a-5b9f-a89f-6c4b34a7453c', '1cfdc539-092c-54df-a97e-209d4e463e30', 'b242c6fc-4417-5ea9-a8c5-13842453ab2d', 'A can finish a job in 12 days and B can finish it in 6 days. Working together, how many days will they take?', '3 days', '4 days', '6 days', '9 days', 'B', 'Combined work per day = 1/12 + 1/6 = 3/12 = 1/4, so together they need 4 days.', array['aptitude','time-and-work']::text[], 'StudyVeda original', 'medium', 'published', '2026-10-26T00:05:00.000Z'),
  ('5c93cc40-679b-5585-a6c3-c84e99485509', '9fe02e81-117a-5b9f-a89f-6c4b34a7453c', '1cfdc539-092c-54df-a97e-209d4e463e30', 'b242c6fc-4417-5ea9-a8c5-13842453ab2d', 'If 8 workers build a wall in 15 days, how many days will 12 workers take at the same rate?', '8 days', '10 days', '12 days', '20 days', 'B', 'Total work = 8 × 15 = 120 worker-days. With 12 workers: 120 ÷ 12 = 10 days.', array['aptitude','time-and-work']::text[], 'StudyVeda original', 'easy', 'published', '2026-10-26T00:06:00.000Z'),
  ('072c8f53-9a36-5f90-a8d8-edff52c5cd5f', '9fe02e81-117a-5b9f-a89f-6c4b34a7453c', 'd4cd4f1f-8c78-5fb7-a273-755aa753cd28', '17c77b05-515c-5f69-acb3-22f15e6a4993', 'What is the simple interest on ₹5,000 at 8% per annum for 3 years?', '₹1,000', '₹1,200', '₹1,400', '₹1,500', 'B', 'SI = P × R × T ÷ 100 = 5000 × 8 × 3 ÷ 100 = ₹1,200.', array['aptitude','simple-interest']::text[], 'StudyVeda original', 'easy', 'published', '2026-10-26T00:07:00.000Z'),
  ('a5177afb-f03a-5ab5-abb1-dd0c2ab36872', '9fe02e81-117a-5b9f-a89f-6c4b34a7453c', '69783ace-5563-565c-a3ca-04f0427c11fd', 'b95444e3-f3f0-565d-aa0e-2c621416d98d', 'The average of 5 numbers is 24. If the number 40 is removed, what is the average of the remaining four numbers?', '18', '20', '21', '22', 'B', 'Sum of 5 numbers = 120. After removing 40 the sum is 80, and 80 ÷ 4 = 20.', array['aptitude','averages']::text[], 'StudyVeda original', 'medium', 'published', '2026-10-26T00:08:00.000Z'),
  ('18f5e248-a59b-585d-a6c4-63e912f8e1b9', '9fe02e81-117a-5b9f-a89f-6c4b34a7453c', '143ba360-5d50-5b54-a036-bdcecb91f83b', '0bc285c1-64e9-5197-a8f7-12506bec1c09', 'A train covers 360 km in 4 hours. What is its speed in metres per second?', '20 m/s', '25 m/s', '30 m/s', '90 m/s', 'B', 'Speed = 360 ÷ 4 = 90 km/h. 90 × 5/18 = 25 m/s.', array['aptitude','speed-time-distance']::text[], 'StudyVeda original', 'medium', 'published', '2026-10-26T00:09:00.000Z'),
  ('016b3c48-3df6-5fb4-ab86-dda1ac4ea6cf', 'baa92451-4172-55e7-a56d-6e93eec9f950', 'd0140ef1-004e-5d76-a04d-cafea3d7ce1f', 'b95444e3-f3f0-565d-aa0e-2c621416d98d', 'Choose the word closest in meaning to ''Abundant''.', 'Scarce', 'Plentiful', 'Rare', 'Tiny', 'B', '''Abundant'' means existing in large quantities, so ''Plentiful'' is the synonym.', array['english','synonyms']::text[], 'StudyVeda original', 'easy', 'published', '2026-10-26T00:10:00.000Z'),
  ('0f8abeb8-d791-5edd-a383-10a51addb8b4', 'baa92451-4172-55e7-a56d-6e93eec9f950', 'd0140ef1-004e-5d76-a04d-cafea3d7ce1f', '17c77b05-515c-5f69-acb3-22f15e6a4993', 'Choose the word closest in meaning to ''Candid''.', 'Frank', 'Secretive', 'Cruel', 'Hesitant', 'A', '''Candid'' means truthful and straightforward, which is ''Frank''.', array['english','synonyms']::text[], 'StudyVeda original', 'medium', 'published', '2026-10-26T00:11:00.000Z'),
  ('9237f7fa-feed-5b74-a3a7-5ca7328747f4', 'baa92451-4172-55e7-a56d-6e93eec9f950', '19f2d9a8-c175-5d2c-a636-c7f8f7d16f68', '46801927-a531-5419-a23e-0c739c2646f2', 'Choose the word opposite in meaning to ''Ancient''.', 'Old', 'Modern', 'Historic', 'Antique', 'B', '''Ancient'' means very old; its opposite is ''Modern''.', array['english','antonyms']::text[], 'StudyVeda original', 'easy', 'published', '2026-10-26T00:12:00.000Z'),
  ('ebfd84fc-abe4-50bf-a04e-e94350274d6e', 'baa92451-4172-55e7-a56d-6e93eec9f950', '19f2d9a8-c175-5d2c-a636-c7f8f7d16f68', '17c77b05-515c-5f69-acb3-22f15e6a4993', 'Choose the word opposite in meaning to ''Expand''.', 'Grow', 'Stretch', 'Contract', 'Widen', 'C', 'To ''expand'' is to become larger; to ''contract'' is to become smaller.', array['english','antonyms']::text[], 'StudyVeda original', 'easy', 'published', '2026-10-26T00:13:00.000Z'),
  ('49997f69-1133-5a6e-a6ad-fcc96a2f3812', 'baa92451-4172-55e7-a56d-6e93eec9f950', 'd82e9a21-d50b-5c67-ac4b-7d90e05f553c', 'b95444e3-f3f0-565d-aa0e-2c621416d98d', 'Choose the grammatically correct sentence.', 'She don''t like tea.', 'She doesn''t likes tea.', 'She doesn''t like tea.', 'She not like tea.', 'C', 'With a third-person singular subject we use ''does not'' followed by the base verb: ''She doesn''t like tea.''', array['english','grammar']::text[], 'StudyVeda original', 'easy', 'published', '2026-10-26T00:14:00.000Z'),
  ('b020e26c-00e0-5b82-aa0e-db3c955daf54', 'baa92451-4172-55e7-a56d-6e93eec9f950', 'd82e9a21-d50b-5c67-ac4b-7d90e05f553c', 'b95444e3-f3f0-565d-aa0e-2c621416d98d', 'Fill in the blank: He has been living here ___ 2015.', 'for', 'since', 'from', 'by', 'B', '''Since'' is used with a point in time (2015); ''for'' is used with a duration.', array['english','grammar']::text[], 'StudyVeda original', 'medium', 'published', '2026-10-26T00:15:00.000Z'),
  ('30f37b3d-d3cc-5215-a09d-a319730e5583', 'baa92451-4172-55e7-a56d-6e93eec9f950', 'ae1f4bf5-4cdf-5ad8-a3c5-04c022b1db49', '46801927-a531-5419-a23e-0c739c2646f2', 'Choose the correctly spelt word.', 'Accomodate', 'Acommodate', 'Accommodate', 'Acomodate', 'C', 'The correct spelling has double ''c'' and double ''m'': Accommodate.', array['english','spelling']::text[], 'StudyVeda original', 'medium', 'published', '2026-10-26T00:16:00.000Z'),
  ('178020d7-9bf1-59de-a6f6-4f02817ede42', '32cdfebe-9f18-527a-ac5e-69095f3ca779', 'b9b48af6-748d-55ad-a3bd-7b14eb3364c3', 'b242c6fc-4417-5ea9-a8c5-13842453ab2d', 'Find the next number in the series: 2, 6, 12, 20, 30, ?', '40', '42', '44', '36', 'B', 'The differences are 4, 6, 8, 10, so the next difference is 12: 30 + 12 = 42.', array['verbal-reasoning','series']::text[], 'StudyVeda original', 'easy', 'published', '2026-10-26T00:17:00.000Z'),
  ('e1f64c2f-e142-58f1-a2d1-e606dff837cb', '32cdfebe-9f18-527a-ac5e-69095f3ca779', 'b9b48af6-748d-55ad-a3bd-7b14eb3364c3', 'b242c6fc-4417-5ea9-a8c5-13842453ab2d', 'Find the next term in the series: A, C, F, J, ?', 'M', 'N', 'O', 'P', 'C', 'Letter positions are 1, 3, 6, 10 (gaps +2, +3, +4). The next gap is +5, giving 15 = O.', array['verbal-reasoning','series']::text[], 'StudyVeda original', 'medium', 'published', '2026-10-26T00:18:00.000Z'),
  ('a6305649-c8f5-5435-a589-6671fd3065e2', '32cdfebe-9f18-527a-ac5e-69095f3ca779', '942622b7-c37c-5815-adc2-1b4a149ae1a8', 'b95444e3-f3f0-565d-aa0e-2c621416d98d', 'If CAT is coded as DBU, how is DOG coded in the same way?', 'EPH', 'EPG', 'DPH', 'FPH', 'A', 'Each letter moves one place forward: D→E, O→P, G→H, so DOG becomes EPH.', array['verbal-reasoning','coding-decoding']::text[], 'StudyVeda original', 'easy', 'published', '2026-10-26T00:19:00.000Z'),
  ('e855f80e-94e6-57d4-a495-01f69c3f7afc', '32cdfebe-9f18-527a-ac5e-69095f3ca779', '95cbb7f6-8252-5e84-a325-2e6bfc422b4a', '17c77b05-515c-5f69-acb3-22f15e6a4993', 'Pointing to a man, Riya says, ''He is the son of my mother''s only brother.'' How is the man related to Riya?', 'Brother', 'Cousin', 'Nephew', 'Uncle', 'B', 'Riya''s mother''s only brother is Riya''s maternal uncle; his son is Riya''s cousin.', array['verbal-reasoning','blood-relations']::text[], 'StudyVeda original', 'medium', 'published', '2026-10-26T00:20:00.000Z'),
  ('1e513c9d-c383-5f29-a334-5f8826d8044d', '32cdfebe-9f18-527a-ac5e-69095f3ca779', 'ca06657e-504e-546c-a45d-2a69ae27e70b', '0bc285c1-64e9-5197-a8f7-12506bec1c09', 'Ravi walks 5 km north, turns right and walks 3 km, then turns right again and walks 5 km. How far is he from his starting point?', '3 km', '5 km', '8 km', '13 km', 'A', 'He goes north 5 km, east 3 km and then south 5 km, ending 3 km east of where he started.', array['verbal-reasoning','direction-sense']::text[], 'StudyVeda original', 'medium', 'published', '2026-10-26T00:21:00.000Z'),
  ('811f7d20-fdd7-5d84-a09e-46f72b97102a', '32cdfebe-9f18-527a-ac5e-69095f3ca779', '7c0da678-4e32-53ff-ac2a-833828ca5d1e', '46801927-a531-5419-a23e-0c739c2646f2', 'Find the odd one out: Apple, Mango, Potato, Banana', 'Apple', 'Mango', 'Potato', 'Banana', 'C', 'Apple, Mango and Banana are fruits; Potato is a vegetable (a tuber).', array['verbal-reasoning','classification']::text[], 'StudyVeda original', 'easy', 'published', '2026-10-26T00:22:00.000Z'),
  ('75d4a6be-ada3-5440-a61f-c9186bc4a6a2', '9da67055-38cc-5576-aaa1-e236ef4d5b2c', '250ebe84-6e5f-5df1-a61a-078c097f4604', 'b95444e3-f3f0-565d-aa0e-2c621416d98d', 'Who is known as the chief architect of the Indian Constitution?', 'Jawaharlal Nehru', 'B. R. Ambedkar', 'Mahatma Gandhi', 'Sardar Vallabhbhai Patel', 'B', 'Dr B. R. Ambedkar chaired the Drafting Committee of the Constituent Assembly.', array['general-knowledge','indian-polity']::text[], 'StudyVeda original', 'easy', 'published', '2026-10-26T00:23:00.000Z'),
  ('c5668e56-9a3f-58b6-a85c-39370f652332', '9da67055-38cc-5576-aaa1-e236ef4d5b2c', '250ebe84-6e5f-5df1-a61a-078c097f4604', 'b242c6fc-4417-5ea9-a8c5-13842453ab2d', 'On which date did the Constitution of India come into force?', '15 August 1947', '26 January 1950', '26 November 1949', '2 October 1950', 'B', 'The Constitution was adopted on 26 November 1949 and came into force on 26 January 1950, celebrated as Republic Day.', array['general-knowledge','indian-polity']::text[], 'StudyVeda original', 'easy', 'published', '2026-10-26T00:24:00.000Z'),
  ('64c4c415-5678-5f94-a02e-21ac447ffc94', '9da67055-38cc-5576-aaa1-e236ef4d5b2c', 'adb8fe4c-0361-55ce-a2e1-4e33b05e29ee', '0bc285c1-64e9-5197-a8f7-12506bec1c09', 'Which river is popularly called the ''Dakshin Ganga''?', 'Godavari', 'Krishna', 'Kaveri', 'Narmada', 'A', 'The Godavari, the longest river of peninsular India, is often called the ''Dakshin Ganga''.', array['general-knowledge','geography']::text[], 'StudyVeda original', 'medium', 'published', '2026-10-26T00:25:00.000Z'),
  ('0b4be4a4-0cee-56a0-a7f2-f1f1ad4338cd', '9da67055-38cc-5576-aaa1-e236ef4d5b2c', 'adb8fe4c-0361-55ce-a2e1-4e33b05e29ee', 'b03b799c-11ad-57e4-afff-26549568e0cf', 'Which is the largest state of India by area?', 'Madhya Pradesh', 'Maharashtra', 'Rajasthan', 'Uttar Pradesh', 'C', 'Rajasthan is the largest Indian state by area.', array['general-knowledge','geography']::text[], 'StudyVeda original', 'easy', 'published', '2026-10-26T00:26:00.000Z'),
  ('bdb072e7-9dde-580a-ae01-2cb3c6716cad', '9da67055-38cc-5576-aaa1-e236ef4d5b2c', '3ee4b5fc-7992-58da-af57-0cc5a2c37f87', '0bc285c1-64e9-5197-a8f7-12506bec1c09', 'In which year was the Battle of Plassey fought?', '1757', '1764', '1857', '1526', 'A', 'The Battle of Plassey (1757) saw the East India Company defeat Siraj-ud-Daulah of Bengal.', array['general-knowledge','history']::text[], 'StudyVeda original', 'easy', 'published', '2026-10-26T00:27:00.000Z'),
  ('e3bc649f-b0a3-5cb5-afe1-7f4905c34880', '9da67055-38cc-5576-aaa1-e236ef4d5b2c', '3ee4b5fc-7992-58da-af57-0cc5a2c37f87', 'b03b799c-11ad-57e4-afff-26549568e0cf', 'Who founded the Maurya Empire?', 'Ashoka', 'Bindusara', 'Chandragupta Maurya', 'Chanakya', 'C', 'Chandragupta Maurya founded the empire around 322 BCE, with Chanakya as his adviser.', array['general-knowledge','history']::text[], 'StudyVeda original', 'easy', 'published', '2026-10-26T00:28:00.000Z'),
  ('740e6b4c-24c1-516e-a4af-4be7ab5f55de', '4b17cd90-f80e-52e9-afd0-8aa1bfca9226', '89f4d45d-9525-5f57-af18-81b54512f23a', '0bc285c1-64e9-5197-a8f7-12506bec1c09', 'What is the SI unit of force?', 'Joule', 'Newton', 'Watt', 'Pascal', 'B', 'Force is measured in newtons (N); 1 N = 1 kg·m/s².', array['general-science','physics']::text[], 'StudyVeda original', 'easy', 'published', '2026-10-26T00:29:00.000Z'),
  ('96ea5a17-0c39-5204-ab48-e8e85f87a87d', '4b17cd90-f80e-52e9-afd0-8aa1bfca9226', '1eaa8771-d812-5a32-a205-fff522e61ea0', '0bc285c1-64e9-5197-a8f7-12506bec1c09', 'What is the chemical formula of common salt?', 'NaCl', 'KCl', 'Na₂CO₃', 'NaOH', 'A', 'Common salt is sodium chloride, NaCl.', array['general-science','chemistry']::text[], 'StudyVeda original', 'easy', 'published', '2026-10-26T00:30:00.000Z'),
  ('590b4e49-5811-53f3-a02f-f04021c71a76', '4b17cd90-f80e-52e9-afd0-8aa1bfca9226', 'ecc8ff10-5517-5857-a7e1-acd4b9db5560', 'b03b799c-11ad-57e4-afff-26549568e0cf', 'Which cell organelle is known as the powerhouse of the cell?', 'Nucleus', 'Ribosome', 'Mitochondria', 'Golgi body', 'C', 'Mitochondria produce most of the cell’s ATP through cellular respiration.', array['general-science','biology']::text[], 'StudyVeda original', 'easy', 'published', '2026-10-26T00:31:00.000Z'),
  ('7aaf4aa5-af7f-5a0e-accf-7eb32d98b33e', '4b17cd90-f80e-52e9-afd0-8aa1bfca9226', 'ecc8ff10-5517-5857-a7e1-acd4b9db5560', '46801927-a531-5419-a23e-0c739c2646f2', 'Which vitamin is produced by the human skin when exposed to sunlight?', 'Vitamin A', 'Vitamin B12', 'Vitamin C', 'Vitamin D', 'D', 'UV-B rays in sunlight help the skin synthesise vitamin D.', array['general-science','biology']::text[], 'StudyVeda original', 'easy', 'published', '2026-10-26T00:32:00.000Z'),
  ('a3dbf477-fbe0-51af-a938-8faaf1cc25bb', '96919549-ef3b-58f9-a979-55558596f38e', '22beb678-65e5-55a8-aed5-2c9bb5dce234', '17c77b05-515c-5f69-acb3-22f15e6a4993', 'What does CPU stand for?', 'Central Processing Unit', 'Central Program Unit', 'Computer Personal Unit', 'Control Processing Unit', 'A', 'CPU stands for Central Processing Unit, the component that executes instructions.', array['computer-fundamentals','basics']::text[], 'StudyVeda original', 'easy', 'published', '2026-10-26T00:33:00.000Z'),
  ('8bca75b6-f303-50f0-ae49-79cff5a437f4', '96919549-ef3b-58f9-a979-55558596f38e', '22beb678-65e5-55a8-aed5-2c9bb5dce234', 'b242c6fc-4417-5ea9-a8c5-13842453ab2d', 'Which of the following is volatile memory?', 'ROM', 'RAM', 'Hard disk', 'Flash drive', 'B', 'RAM loses its contents when power is switched off, so it is volatile.', array['computer-fundamentals','basics']::text[], 'StudyVeda original', 'easy', 'published', '2026-10-26T00:34:00.000Z'),
  ('40c6e2a6-5de9-50c5-a082-c060dafbc305', '96919549-ef3b-58f9-a979-55558596f38e', '22beb678-65e5-55a8-aed5-2c9bb5dce234', 'b95444e3-f3f0-565d-aa0e-2c621416d98d', 'In the binary convention, 1 kilobyte (KB) is equal to', '1000 bytes', '1024 bytes', '1024 bits', '512 bytes', 'B', 'In binary terms 1 KB = 2¹⁰ = 1024 bytes.', array['computer-fundamentals','basics']::text[], 'StudyVeda original', 'medium', 'published', '2026-10-26T00:35:00.000Z'),
  ('249286ad-d98e-5ac7-a01a-6ce66214dfa5', '96919549-ef3b-58f9-a979-55558596f38e', '9fc602e0-403f-5b87-ae00-cae4576064de', '46801927-a531-5419-a23e-0c739c2646f2', 'Which of the following is an operating system?', 'Linux', 'MS Excel', 'Python', 'Photoshop', 'A', 'Linux is an operating system; the others are applications or a programming language.', array['computer-fundamentals','software']::text[], 'StudyVeda original', 'easy', 'published', '2026-10-26T00:36:00.000Z'),
  ('c59616e4-6174-5cd2-ad22-4dcca85f60e7', '96919549-ef3b-58f9-a979-55558596f38e', '9fc602e0-403f-5b87-ae00-cae4576064de', '17c77b05-515c-5f69-acb3-22f15e6a4993', 'Which keyboard shortcut copies selected content in Windows?', 'Ctrl + V', 'Ctrl + X', 'Ctrl + C', 'Ctrl + Z', 'C', 'Ctrl + C copies, Ctrl + X cuts, Ctrl + V pastes and Ctrl + Z undoes.', array['computer-fundamentals','software']::text[], 'StudyVeda original', 'easy', 'published', '2026-10-26T00:37:00.000Z'),
  ('1e68c6ee-6bd5-5b50-a802-2cb4c8dbd648', '704d5f19-7ff1-5353-ad94-9ae58d0b1c61', 'bba3dfb9-ed82-5c76-a8f2-6c56d1286331', null, 'How many layers does the OSI reference model have?', '4', '5', '7', '8', 'C', 'The OSI model has 7 layers: Physical, Data Link, Network, Transport, Session, Presentation and Application.', array['networking','network-basics']::text[], 'StudyVeda original', 'easy', 'published', '2026-10-26T00:38:00.000Z'),
  ('740bd6c1-99ff-5269-a899-9ecf3839eae6', '704d5f19-7ff1-5353-ad94-9ae58d0b1c61', '2f8bc59a-bbdd-55f5-a002-35359f0936da', null, 'Which protocol automatically assigns IP addresses to devices on a network?', 'DNS', 'DHCP', 'FTP', 'SMTP', 'B', 'DHCP (Dynamic Host Configuration Protocol) leases IP addresses to clients.', array['networking','protocols']::text[], 'StudyVeda original', 'medium', 'published', '2026-10-26T00:39:00.000Z'),
  ('94cc7fa7-5cea-533a-ac73-382d073a3726', '704d5f19-7ff1-5353-ad94-9ae58d0b1c61', '2f8bc59a-bbdd-55f5-a002-35359f0936da', null, 'What is the default port number for HTTPS?', '80', '21', '443', '25', 'C', 'HTTPS uses port 443; HTTP uses 80, FTP 21 and SMTP 25.', array['networking','protocols']::text[], 'StudyVeda original', 'easy', 'published', '2026-10-26T00:40:00.000Z'),
  ('409bf2d1-adc5-59b4-a551-2a6746456718', '704d5f19-7ff1-5353-ad94-9ae58d0b1c61', 'bba3dfb9-ed82-5c76-a8f2-6c56d1286331', null, 'How many bits are there in an IPv4 address?', '16', '32', '64', '128', 'B', 'An IPv4 address is 32 bits long; IPv6 addresses are 128 bits.', array['networking','network-basics']::text[], 'StudyVeda original', 'easy', 'published', '2026-10-26T00:41:00.000Z'),
  ('ba0b9299-cf66-5c3d-adb7-63a46d2c1c48', 'ed50916d-ad00-5f9f-a08e-d13183a006de', 'e27f6ef3-d385-58ac-a4d0-f981f5311eec', null, 'Which normal form removes partial dependency of non-key attributes on a composite key?', '1NF', '2NF', '3NF', 'BCNF', 'B', 'Second Normal Form requires every non-key attribute to depend on the whole primary key.', array['database','normalization']::text[], 'StudyVeda original', 'medium', 'published', '2026-10-26T00:42:00.000Z'),
  ('884addaf-6650-5206-a499-571ce6bd9bdb', 'ed50916d-ad00-5f9f-a08e-d13183a006de', 'cae144bd-4bca-5e1d-a24f-49d50b9ee97e', null, 'Which statement about a primary key is true?', 'It can contain NULL values', 'It must be unique and not NULL', 'It may contain duplicate values', 'It must always be a text column', 'B', 'A primary key uniquely identifies each row, so it must be unique and cannot be NULL.', array['database','keys-and-transactions']::text[], 'StudyVeda original', 'easy', 'published', '2026-10-26T00:43:00.000Z'),
  ('e4d147d5-6f0c-5d86-ab99-74284616cefd', 'ed50916d-ad00-5f9f-a08e-d13183a006de', 'cae144bd-4bca-5e1d-a24f-49d50b9ee97e', null, 'In the ACID properties of transactions, what does ''A'' stand for?', 'Accuracy', 'Atomicity', 'Availability', 'Authorization', 'B', 'Atomicity means a transaction completes fully or not at all.', array['database','keys-and-transactions']::text[], 'StudyVeda original', 'easy', 'published', '2026-10-26T00:44:00.000Z'),
  ('94482fa5-5a12-5c52-a7c3-a3a8040af528', 'ca88a952-274f-56ac-abd9-18e37cb1de9d', '46a2505c-69ea-5cc7-ac02-516b37f693f9', null, 'Which SQL clause filters groups after a GROUP BY?', 'WHERE', 'HAVING', 'ORDER BY', 'LIMIT', 'B', 'WHERE filters rows before grouping; HAVING filters the grouped results.', array['sql','queries']::text[], 'StudyVeda original', 'medium', 'published', '2026-10-26T00:45:00.000Z'),
  ('a7e71ea3-2f2f-5d7b-a1c0-7ec30d7e2411', 'ca88a952-274f-56ac-abd9-18e37cb1de9d', '46a2505c-69ea-5cc7-ac02-516b37f693f9', null, 'Which command removes all rows from a table but keeps its structure, without allowing a WHERE condition?', 'DELETE', 'DROP', 'TRUNCATE', 'ALTER', 'C', 'TRUNCATE empties the table; DROP removes the table itself; DELETE can use WHERE.', array['sql','queries']::text[], 'StudyVeda original', 'medium', 'published', '2026-10-26T00:46:00.000Z'),
  ('0d09034c-5e90-5c67-a3ba-34e837504528', 'ca88a952-274f-56ac-abd9-18e37cb1de9d', '46a2505c-69ea-5cc7-ac02-516b37f693f9', null, 'Which aggregate function returns the number of rows?', 'SUM()', 'COUNT()', 'MAX()', 'AVG()', 'B', 'COUNT() counts rows (or non-NULL values of a column).', array['sql','queries']::text[], 'StudyVeda original', 'easy', 'published', '2026-10-26T00:47:00.000Z'),
  ('477ef140-3bc7-58cb-a5cb-a0500ec9f0cd', 'ca88a952-274f-56ac-abd9-18e37cb1de9d', '2e4c8ea1-a693-598a-a278-e2594baca082', null, 'Which join returns all rows from the left table and the matching rows from the right table?', 'INNER JOIN', 'LEFT JOIN', 'RIGHT JOIN', 'CROSS JOIN', 'B', 'A LEFT JOIN keeps every row of the left table and fills NULLs where there is no match.', array['sql','joins']::text[], 'StudyVeda original', 'easy', 'published', '2026-10-26T00:48:00.000Z'),
  ('fe6cddd3-7c8c-599f-afdf-cf321e5eee5b', '5a5be63b-7afa-5272-a3b8-7c09ef0a485d', 'a657d37f-a0bf-5444-a988-5a06726e1484', null, 'Which format specifier prints an int in C?', '%f', '%c', '%d', '%s', 'C', '%d prints a signed decimal integer; %f is for floating point, %c for char and %s for strings.', array['c-programming','c-basics']::text[], 'StudyVeda original', 'easy', 'published', '2026-10-26T00:49:00.000Z'),
  ('a3246a0b-e689-583f-abc9-468cb4a84f1b', '5a5be63b-7afa-5272-a3b8-7c09ef0a485d', 'a657d37f-a0bf-5444-a988-5a06726e1484', null, 'What is sizeof(char) in C?', '1', '2', '4', '8', 'A', 'The C standard defines sizeof(char) as exactly 1.', array['c-programming','c-basics']::text[], 'StudyVeda original', 'easy', 'published', '2026-10-26T00:50:00.000Z'),
  ('beac92b4-fefa-50c7-a78f-cccd49d6523d', '5a5be63b-7afa-5272-a3b8-7c09ef0a485d', 'a657d37f-a0bf-5444-a988-5a06726e1484', null, 'What does printf("%d", 7 / 2); print in C?', '3.5', '3', '4', '3.0', 'B', 'Both operands are integers, so integer division truncates 3.5 to 3.', array['c-programming','c-basics']::text[], 'StudyVeda original', 'medium', 'published', '2026-10-26T00:51:00.000Z'),
  ('c936c0fa-159d-5560-a0e4-a697d60a4e3c', 'dee79a7c-223a-5be5-a7e0-fad4d4aacfba', '6aae082c-8607-52a3-a01b-6dd2cf2ed91d', null, 'Which operator is the scope resolution operator in C++?', '::', '->', '.', '#', 'A', 'The :: operator accesses a name inside a namespace or class scope.', array['cpp-programming','oop']::text[], 'StudyVeda original', 'easy', 'published', '2026-10-26T00:52:00.000Z'),
  ('c53118cb-398a-5a9d-a400-161ebb7535ea', 'dee79a7c-223a-5be5-a7e0-fad4d4aacfba', '6aae082c-8607-52a3-a01b-6dd2cf2ed91d', null, 'Function overloading in C++ is an example of which OOP concept?', 'Encapsulation', 'Inheritance', 'Polymorphism', 'Abstraction', 'C', 'Overloading lets one function name take many forms — compile-time polymorphism.', array['cpp-programming','oop']::text[], 'StudyVeda original', 'easy', 'published', '2026-10-26T00:53:00.000Z'),
  ('03577c69-44d3-510d-a970-6819f9aa7c8a', '0ce4fcf0-ae04-541a-af89-e32592d71a06', '688df583-5031-59c5-ace7-9b12f7cf37d5', null, 'Which keyword is used by a class to inherit another class in Java?', 'implements', 'extends', 'inherits', 'super', 'B', 'A class uses ''extends'' to inherit a class and ''implements'' for interfaces.', array['java','java-basics']::text[], 'StudyVeda original', 'easy', 'published', '2026-10-26T00:54:00.000Z'),
  ('57e1f975-6c30-573a-afdf-e80012efd263', '0ce4fcf0-ae04-541a-af89-e32592d71a06', '688df583-5031-59c5-ace7-9b12f7cf37d5', null, 'Java bytecode is executed by the', 'javac compiler', 'Java Virtual Machine (JVM)', 'JDK installer', 'operating system kernel directly', 'B', 'javac compiles source to bytecode, which the JVM then executes.', array['java','java-basics']::text[], 'StudyVeda original', 'easy', 'published', '2026-10-26T00:55:00.000Z'),
  ('45744a91-5b70-5fbe-ac25-f80d68c374d1', '0ce4fcf0-ae04-541a-af89-e32592d71a06', '688df583-5031-59c5-ace7-9b12f7cf37d5', null, 'What is the default value of an int instance variable in Java?', '0', 'null', '1', 'Undefined', 'A', 'Numeric instance fields default to 0; object references default to null.', array['java','java-basics']::text[], 'StudyVeda original', 'medium', 'published', '2026-10-26T00:56:00.000Z'),
  ('871944db-f14f-519e-a73f-965d3d9bd918', 'eee4de76-7d87-514c-a039-68f4aa8a00d0', 'faf5c0c0-683f-5db9-aebf-3cd611c41f13', null, 'What is the output of print(type([])) in Python 3?', '<class ''list''>', '<class ''tuple''>', '<class ''dict''>', '<class ''array''>', 'A', '[] creates an empty list, so type([]) is list.', array['python','python-basics']::text[], 'StudyVeda original', 'easy', 'published', '2026-10-26T00:57:00.000Z'),
  ('9a50f167-f814-5e1d-a067-b6665dff4be5', 'eee4de76-7d87-514c-a039-68f4aa8a00d0', 'faf5c0c0-683f-5db9-aebf-3cd611c41f13', null, 'Which keyword is used to define a function in Python?', 'func', 'def', 'function', 'define', 'B', 'Functions are defined with ''def'', e.g. def greet():', array['python','python-basics']::text[], 'StudyVeda original', 'easy', 'published', '2026-10-26T00:58:00.000Z'),
  ('faed6a4e-d68b-5cb3-ae73-eb736c86a4c1', 'eee4de76-7d87-514c-a039-68f4aa8a00d0', 'faf5c0c0-683f-5db9-aebf-3cd611c41f13', null, 'What does len(''StudyVeda'') return?', '8', '9', '10', '7', 'B', '''StudyVeda'' has 9 characters: S-t-u-d-y-V-e-d-a.', array['python','python-basics']::text[], 'StudyVeda original', 'easy', 'published', '2026-10-26T00:59:00.000Z'),
  ('de330614-e7aa-55cf-ad9b-c269d533eb13', 'eee4de76-7d87-514c-a039-68f4aa8a00d0', '75ff4c0b-5c91-5454-aa76-a0227660c0dd', null, 'Which of these Python data types is immutable?', 'list', 'dict', 'set', 'tuple', 'D', 'Tuples cannot be changed after creation; lists, dicts and sets are mutable.', array['python','data-types']::text[], 'StudyVeda original', 'easy', 'published', '2026-10-26T01:00:00.000Z'),
  ('470b1cad-723c-581d-a1ce-b4c84309a500', 'eee4de76-7d87-514c-a039-68f4aa8a00d0', 'ab6508f1-94ea-51a2-a311-c6dc5c83ec5d', null, 'What is the output of print(2 ** 3)?', '6', '8', '9', '5', 'B', '** is the exponent operator: 2³ = 8.', array['python','operators']::text[], 'StudyVeda original', 'easy', 'published', '2026-10-26T01:01:00.000Z'),
  ('4d7df47f-ab92-5b30-a254-b123595ccf8f', 'eee4de76-7d87-514c-a039-68f4aa8a00d0', 'ab6508f1-94ea-51a2-a311-c6dc5c83ec5d', null, 'What is the output of print(10 // 3)?', '3.33', '3', '4', '1', 'B', '// is floor division, so 10 // 3 = 3. (10 % 3 would give 1.)', array['python','operators']::text[], 'StudyVeda original', 'medium', 'published', '2026-10-26T01:02:00.000Z'),
  ('8d8fb073-9f7c-50ea-af67-afe85887c702', '31b3aace-46cf-5847-a021-afb704e7a039', '106c48e5-c2c8-5219-a7e2-c6b1f5999bde', null, 'What does typeof null return in JavaScript?', '''null''', '''object''', '''undefined''', '''number''', 'B', 'A long-standing quirk of JavaScript: typeof null is ''object''.', array['javascript','js-basics']::text[], 'StudyVeda original', 'medium', 'published', '2026-10-26T01:03:00.000Z'),
  ('e529a23b-c1ed-56bb-a1e3-5d058db3d29c', '31b3aace-46cf-5847-a021-afb704e7a039', '106c48e5-c2c8-5219-a7e2-c6b1f5999bde', null, 'Which keyword declares a block-scoped variable that cannot be reassigned?', 'var', 'let', 'const', 'static', 'C', '''const'' is block-scoped and cannot be reassigned; ''let'' can be reassigned.', array['javascript','js-basics']::text[], 'StudyVeda original', 'easy', 'published', '2026-10-26T01:04:00.000Z'),
  ('f3db38bd-3903-598f-aa35-19a33c846c09', '31b3aace-46cf-5847-a021-afb704e7a039', '106c48e5-c2c8-5219-a7e2-c6b1f5999bde', null, 'What is the result of ''5'' + 3 in JavaScript?', '8', '''53''', 'NaN', 'A TypeError', 'B', 'With a string operand, + performs concatenation, producing the string "53".', array['javascript','js-basics']::text[], 'StudyVeda original', 'medium', 'published', '2026-10-26T01:05:00.000Z'),
  ('2eb41a6b-9abf-59ad-ac17-6d28aa229fc9', '598d9866-1a3c-56df-adb4-8fea96aa7135', '42e84c6b-2ead-595d-a842-79618c4c30a7', null, 'Which measure of central tendency is least affected by extreme outliers?', 'Mean', 'Median', 'Range', 'Standard deviation', 'B', 'The median depends on the middle value, so a few extreme values barely move it.', array['data-science','statistics']::text[], 'StudyVeda original', 'easy', 'published', '2026-10-26T01:06:00.000Z'),
  ('d26694ab-84b3-55a1-a642-1f6f67bd7482', '598d9866-1a3c-56df-adb4-8fea96aa7135', 'fa4a7c0c-ae53-59e9-a660-17ee67d52538', null, 'Which pandas function reads a CSV file into a DataFrame?', 'pd.read_csv()', 'pd.load_csv()', 'pd.open_csv()', 'pd.csv()', 'A', 'pd.read_csv("file.csv") returns a DataFrame.', array['data-science','pandas']::text[], 'StudyVeda original', 'easy', 'published', '2026-10-26T01:07:00.000Z'),
  ('e28b7aba-5b88-5583-a6e8-6eb288d3c118', '2eb4a4a3-7ae3-552b-a674-217825697501', '4565ed02-50d5-594a-a9b5-e7ea8eafe041', null, 'Predicting house prices from features such as area and location is an example of', 'Classification', 'Regression', 'Clustering', 'Dimensionality reduction', 'B', 'The target (price) is a continuous number, so this is a regression task.', array['machine-learning','ml-basics']::text[], 'StudyVeda original', 'easy', 'published', '2026-10-26T01:08:00.000Z'),
  ('6cfc7043-bb43-50f4-ae0c-537aa884ad75', '2eb4a4a3-7ae3-552b-a674-217825697501', '4565ed02-50d5-594a-a9b5-e7ea8eafe041', null, 'A model is said to be overfitting when it', 'performs well on training data but poorly on new data', 'performs poorly on both training and new data', 'performs well on both training and new data', 'was trained with too few CPU cores', 'A', 'Overfitting means the model memorised the training data and fails to generalise.', array['machine-learning','ml-basics']::text[], 'StudyVeda original', 'medium', 'published', '2026-10-26T01:09:00.000Z'),
  ('06dd26d3-059e-568c-a7b9-68680ceb86bc', '6dc441be-0635-5985-a60e-df8b509b8ae4', 'f74f2d4a-9c7a-553c-a981-8ab07cad9224', null, 'In the IaaS model, which of the following is usually managed by the customer?', 'Physical servers', 'Data-centre power supply', 'Operating system', 'Network cabling', 'C', 'IaaS providers manage the hardware; customers manage the OS, runtime and applications.', array['cloud-computing','service-models']::text[], 'StudyVeda original', 'medium', 'published', '2026-10-26T01:10:00.000Z'),
  ('d74a4682-1f26-5010-aad1-b4504260ca3b', '6dc441be-0635-5985-a60e-df8b509b8ae4', 'f74f2d4a-9c7a-553c-a981-8ab07cad9224', null, 'What does SaaS stand for?', 'Software as a Service', 'Storage as a System', 'Server as a Service', 'Security as a Solution', 'A', 'SaaS delivers complete applications over the internet, e.g. web email.', array['cloud-computing','service-models']::text[], 'StudyVeda original', 'easy', 'published', '2026-10-26T01:11:00.000Z'),
  ('b9d5aab7-9b65-5b3e-a8d1-7a6a150b71e8', 'a9c844e6-6460-511a-aafd-488a712ac1b2', '48f64bae-5488-5452-ab2f-31d25de08204', null, 'What is the worst-case time complexity of binary search on n sorted elements?', 'O(1)', 'O(log n)', 'O(n)', 'O(n log n)', 'B', 'Binary search halves the search space at every step, giving O(log n).', array['computer-science','algorithms']::text[], 'StudyVeda original', 'easy', 'published', '2026-10-26T01:12:00.000Z'),
  ('10d4161c-e338-54ba-ae7f-719208387124', 'a9c844e6-6460-511a-aafd-488a712ac1b2', 'cf54f6f0-9c02-592f-aa17-e771e1d857c8', null, 'Which data structure follows the LIFO principle?', 'Queue', 'Stack', 'Linked list', 'Heap', 'B', 'A stack is Last In, First Out; a queue is First In, First Out.', array['computer-science','data-structures']::text[], 'StudyVeda original', 'easy', 'published', '2026-10-26T01:13:00.000Z'),
  ('8978dbb0-5b9f-57c2-aea9-101f93dcc185', 'a26371db-431a-5481-a8fe-9c8469e37ebf', 'ea6fe2b5-738d-5bcb-a573-d60134b7bcea', null, 'What is the derivative of sin x with respect to x?', 'cos x', '−cos x', '−sin x', 'tan x', 'A', 'd/dx (sin x) = cos x.', array['engineering-mathematics','calculus']::text[], 'StudyVeda original', 'easy', 'published', '2026-10-26T01:14:00.000Z'),
  ('7f625f45-ac01-530d-acb7-a2abe827555f', 'a26371db-431a-5481-a8fe-9c8469e37ebf', '4dd0fc89-ca3c-5ee6-abd4-d3f4b49209e5', null, 'What is the determinant of the matrix [[2, 3], [1, 4]]?', '5', '8', '11', '2', 'A', 'det = (2 × 4) − (3 × 1) = 8 − 3 = 5.', array['engineering-mathematics','linear-algebra']::text[], 'StudyVeda original', 'easy', 'published', '2026-10-26T01:15:00.000Z'),
  ('9f04840f-72bb-58f8-ad8b-ac1ae724d772', 'ffa7cf62-6e97-53b0-af2b-6281fba7f48b', '1af45c61-b62b-51b7-a810-3cb4cb46d683', '32641e7d-2d57-5105-a76d-bded85f36f49', 'What is the approximate speed of light in vacuum?', '3 × 10⁸ m/s', '3 × 10⁶ m/s', '3 × 10⁵ m/s', '3 × 10¹⁰ m/s', 'A', 'Light travels at about 3 × 10⁸ m/s (299,792,458 m/s exactly) in vacuum.', array['engineering-physics','optics']::text[], 'StudyVeda original', 'easy', 'published', '2026-10-26T01:16:00.000Z'),
  ('e5dfaccc-950c-5640-a562-e1bb3389ad23', 'ff6211ca-390b-5987-a51a-db65d4d922c6', '9adc58f2-54ac-5072-a4de-524c2d3c1d77', null, 'The repo rate is the rate at which', 'the RBI lends short-term funds to commercial banks', 'commercial banks lend to the public', 'the RBI borrows money from commercial banks', 'banks pay interest on savings accounts', 'A', 'Repo rate is the RBI’s lending rate to banks against government securities; reverse repo is the opposite flow.', array['banking-awareness','rbi-and-monetary-policy']::text[], 'StudyVeda original', 'medium', 'published', '2026-10-26T01:17:00.000Z'),
  ('96912d24-0352-5af1-a61f-c0b3a938ecb0', 'ff6211ca-390b-5987-a51a-db65d4d922c6', 'e8274734-fc87-5ba6-a9a3-aa975f622d91', null, 'What does NEFT stand for?', 'National Electronic Funds Transfer', 'Net Electronic Fund Transaction', 'National Easy Funds Transfer', 'New Electronic Finance Transfer', 'A', 'NEFT is the National Electronic Funds Transfer system operated by the RBI.', array['banking-awareness','payment-systems']::text[], 'StudyVeda original', 'easy', 'published', '2026-10-26T01:18:00.000Z'),
  ('876a15d5-6674-5e6f-ab66-5534163297b2', '0ef772a7-bf2d-536f-a501-e8e8d8dc83e5', '3781f446-febf-5366-af12-fa9441988692', null, 'Which of the following is the basic accounting equation?', 'Assets = Liabilities + Capital', 'Assets = Liabilities − Capital', 'Capital = Assets + Liabilities', 'Liabilities = Assets + Capital', 'A', 'Everything a business owns (assets) is financed by outsiders (liabilities) or owners (capital).', array['commerce','accounting']::text[], 'StudyVeda original', 'easy', 'published', '2026-10-26T01:19:00.000Z'),
  ('5f3393b6-1bff-5bd3-af76-df186dd03048', '798eb9e0-5884-5fe5-a3d3-8c7d4985bb7b', '86d56697-80fc-54d2-a41a-636546d3d892', null, 'Who is regarded as the ''Father of Scientific Management''?', 'F. W. Taylor', 'Henri Fayol', 'Peter Drucker', 'Elton Mayo', 'A', 'Frederick Winslow Taylor developed scientific management in the early 1900s.', array['management','principles-of-management']::text[], 'StudyVeda original', 'easy', 'published', '2026-10-26T01:20:00.000Z'),
  ('d3119527-0455-5afd-aef4-34afb046bbf2', '3cacaa9f-aa5f-5444-ab73-9b40a1e7a4f0', '2bbae5d4-e041-56ae-a515-e3ce5e6c74f2', null, 'Fundamental Rights are contained in which Part of the Constitution of India?', 'Part II', 'Part III', 'Part IV', 'Part V', 'B', 'Part III (Articles 12–35) contains the Fundamental Rights; Part IV contains the Directive Principles.', array['law','constitutional-law']::text[], 'StudyVeda original', 'easy', 'published', '2026-10-26T01:21:00.000Z'),
  ('f846cf33-4dc6-54d8-abe4-5e552d17aa6d', '24d93254-1487-5741-a8fc-fbd01f4fd458', '9c69c0dc-4cc4-5873-a629-ca1f6610f8fd', null, 'Who proposed the hierarchy of needs?', 'Abraham Maslow', 'Sigmund Freud', 'B. F. Skinner', 'Jean Piaget', 'A', 'Abraham Maslow proposed the hierarchy of needs in 1943.', array['psychology','theories']::text[], 'StudyVeda original', 'easy', 'published', '2026-10-26T01:22:00.000Z'),
  ('d3049c5d-7730-5994-ad26-31b5c8504a47', '2937b793-9f92-528b-a304-cd4337aca2ae', 'e4a66423-ec00-5754-a0ad-7a762b09e65d', null, 'When asked ''What is your greatest weakness?'', which answer approach is generally best?', 'Say you have no weaknesses', 'Name a genuine weakness and explain how you are improving it', 'Blame your previous employer', 'Name a weakness critical to the job and stop there', 'B', 'Interviewers look for self-awareness and a plan for improvement.', array['hr-interview','common-questions']::text[], 'StudyVeda original', 'easy', 'published', '2026-10-26T01:23:00.000Z'),
  ('00be45fa-551d-5dad-ae5a-4837172634b7', '9fe02e81-117a-5b9f-a89f-6c4b34a7453c', '9d396a89-bf98-504e-a9a9-4fb1e2edb893', null, 'A’s salary is 25% more than B’s. By what percentage is B’s salary less than A’s?', '20%', '25%', '15%', '22.5%', 'A', 'If B = 100, A = 125. B is less by 25 out of 125 = 20%.', array['aptitude','percentage']::text[], 'StudyVeda original', 'hard', 'draft', '2026-10-26T01:24:00.000Z'),
  ('ef540039-8012-56db-a18c-67a3ebf069b3', 'eee4de76-7d87-514c-a039-68f4aa8a00d0', '75ff4c0b-5c91-5454-aa76-a0227660c0dd', null, 'What is the output of print(bool(""))?', 'True', 'False', 'None', 'Error', 'B', 'An empty string is falsy, so bool("") is False.', array['python','data-types']::text[], 'StudyVeda original', 'medium', 'draft', '2026-10-26T01:25:00.000Z')
